import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: handl_plugin_lib_stdlib","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_lib_stdlib/handl_plugin_lib_stdlib.md","filePath":"api/host/handl_plugin_lib_stdlib/handl_plugin_lib_stdlib.md"}`),a={name:`api/host/handl_plugin_lib_stdlib/handl_plugin_lib_stdlib.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_plugin_lib_stdlib</strong></p><h1 id="module-handl-plugin-lib-stdlib" tabindex="-1">Module: handl_plugin_lib_stdlib <a class="header-anchor" href="#module-handl-plugin-lib-stdlib" aria-label="Permalink to “Module: handl_plugin_lib_stdlib”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#arrow-iter"><code>arrow_iter</code></a> - Derived iteration patterns over <code>Loop</code> + <code>Choice</code> (ADR-0052 §&quot;Derived</li><li><a href="#loader"><code>loader</code></a> - Generic on-disk <code>.hnl</code> loader.</li><li><a href="#ops"><code>ops</code></a> - Native op implementations (the Rust &quot;handls&quot;) backing the <code>.hnl</code></li><li><a href="#packages"><code>packages</code></a> - The stdlib <strong>package table</strong> — every handl-backed library is a row of</li></ul><hr><h2 id="module-arrow-iter" tabindex="-1">Module: arrow_iter <a class="header-anchor" href="#module-arrow-iter" aria-label="Permalink to “Module: arrow_iter”">​</a></h2><p>Derived iteration patterns over <code>Loop</code> + <code>Choice</code> (ADR-0052 §&quot;Derived forms&quot;).</p><p>ADR-0052 establishes that <code>while</code>/<code>for</code>/<code>fix</code> are <strong>not</strong> kernel primitives and <strong>not</strong> grammar rules — they are <em>derived patterns</em> expressed via the six arrow-calculus primitives. The load-bearing principle: <strong>feedback is primitive; iteration is derived.</strong> These builders construct [<code>Term</code>] descriptions of <code>while</code>/<code>for</code>/<code>fix</code> from <code>Loop</code> + <code>Arr</code>, with no new kernel constructs.</p><p>Each builder returns a [<code>Term::Loop</code>] whose body is a single <code>Arr</code> composite step op (<code>while_step</code>/<code>for_step</code>/<code>fix_step</code>) carrying the user-supplied sub-arrows (<code>cond</code>/<code>body</code>) as <code>args</code>. The description is primitive-only (<code>Loop</code> + <code>Arr</code>); the <em>interpretation</em> of the composite op lives in the v2 reference handler (<code>hnl-engine-exec-tree-walk</code>), which routes the current value through the carried sub-arrows and produces an <code>Either</code> (<code>left</code> = done, <code>right</code> = continue) consumed by the multi-step <code>Loop</code> handler. This is consistent with ADR-0052&#39;s &quot;handlers interpret&quot; principle: the kernel constructs; the handler decides how to run.</p><p>The multi-step <code>Loop</code> semantics (Either-based: <code>left</code> terminates, <code>right</code> feeds the new state back and re-runs) is what makes these patterns iterate — a single-step <code>Loop</code> could not express repetition on its own.</p><p>The <code>arrow_iter</code> capability surface is declared in <code>handl-packages/arrow_iter/arrow_iter.hnl</code> and folded into the [<code>crate::packages</code>] module table (module <code>&quot;arrow_iter&quot;</code>, package <code>&quot;arrow_iter&quot;</code>).</p><h2 id="module-loader" tabindex="-1">Module: loader <a class="header-anchor" href="#module-loader" aria-label="Permalink to “Module: loader”">​</a></h2><p>Generic on-disk <code>.hnl</code> loader.</p><p>[<code>load_hnl_file</code>] builds a [<code>HandlModule</code>] directly from a <code>.hnl</code> file path, resolving <code>from</code> imports relative to the file&#39;s directory and falling back to the stdlib package table for bare module names such as <code>hash_map</code> or <code>typeof</code>. It is not specific to <code>array</code> — any <code>.hnl</code> package that uses top-level <code>export</code> and <code>from &quot;...&quot; export</code> forms can be loaded from disk.</p><h2 id="module-ops" tabindex="-1">Module: ops <a class="header-anchor" href="#module-ops" aria-label="Permalink to “Module: ops”">​</a></h2><p>Native op implementations (the Rust &quot;handls&quot;) backing the <code>.hnl</code> library packages in [<code>crate::packages</code>].</p><p>Each submodule holds the <code>Function</code> impls plus an <code>*_op_registry()</code> builder registering them under their declared op names (ADR-0077). The impls were moved verbatim from the deleted <code>plugin-lib-*</code> shell crates — only the <code>Module</code>/<code>Plugin</code> boilerplate was dropped.</p><h2 id="module-packages" tabindex="-1">Module: packages <a class="header-anchor" href="#module-packages" aria-label="Permalink to “Module: packages”">​</a></h2><p>The stdlib <strong>package table</strong> — every handl-backed library is a row of data, not a crate.</p><p>A [<code>ModuleSpec</code>] describes one module: its name, its <code>.hnl</code> source (<code>include_str!</code>ed at the call site), the record-field function names, the op names to dispatch via an [<code>OpRegistry</code>], and the names of dependency modules (resolved through a [<code>ModuleResolver</code>]).</p><p>A [<code>PackageSpec</code>] groups modules under one library-plugin name — the key used by kit manifests (<code>modules:</code> entries) and <code>handl_kit_data::LibraryRegistry</code>.</p><p>[<code>module</code>] / [<code>module_ref</code>] build a [<code>HandlModule</code>] for a module name; [<code>library</code>] builds a <code>Box&lt;dyn Plugin&gt;</code> for a package name.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};